import numpy as np
rng = np.random.default_rng(0)
def counts(mean, phi, n):
    if phi < 1.0:
        p = 1.0 - phi; trials = round(mean / p)
        return rng.binomial(max(trials, 1), min(mean/max(trials,1), 1.0), n)
    return rng.poisson(mean, n)
x = counts(0.363, 0.83, 400_000)
print(x.max(), (x >= 3).mean(), x.var()/x.mean())   # 2  0.0  0.817
